import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { SoftwarePackageService } from '../../services/software-package.service';
import { OrderService } from '../../services/order.service';
import { SoftwarePackage } from '../../models/software-package';

@Component({
  selector: 'app-order',
  templateUrl: './order.component.html',
  styleUrls: ['./order.component.css']
})
export class OrderComponent implements OnInit {
  package: SoftwarePackage | null = null;
  loading = false;
  quantity = 1;
  placing = false;
  currentImage = '';
  successMessage = '';
  errorMessage = '';

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private softwarePackageService: SoftwarePackageService,
    private orderService: OrderService
  ) {}

  ngOnInit(): void {
    const id = Number(this.route.snapshot.paramMap.get('id'));
    this.fetchPackage(id);
  }

  fetchPackage(id: number): void {
    this.loading = true;
    this.errorMessage = '';
    this.softwarePackageService.fetchPackageById(id).then((data: SoftwarePackage | null) => {
      this.package = data;
      if (!data) {
        this.errorMessage = 'Software package not found';
      }
    }).finally(() => {
      this.loading = false;
    });
  }

  async placeOrder(): Promise<void> {
    if (!this.package) return;
    this.placing = true;
    this.successMessage = '';
    this.errorMessage = '';
    try {
      await this.orderService.placeOrder(this.package.id, this.quantity);
      this.successMessage = 'Order placed successfully!';
      setTimeout(() => {
        this.router.navigate(['/packages']);
      }, 1500);
    } catch (err: any) {
      this.errorMessage = err.error?.error || 'Failed to place order. Please try again.';
    } finally {
      this.placing = false;
    }
  }

  goBack(): void {
    this.router.navigate(['/packages']);
  }
}
<div class="min-h-screen bg-gray-50">
  <header class="bg-white shadow-sm">
    <div class="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
      <a (click)="goBack()" class="inline-flex items-center text-sm text-gray-600 hover:text-primary">
        <svg class="w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
        </svg>
        Back to Packages
      </a>
    </div>
  </header>

  <main class="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
    <div *ngIf="loading" class="text-center py-8">
      <div class="inline-block animate-spin rounded-full h-3 w-3 border-b-2 border-primary mx-auto"></div>
      <p class="mt-2 text-sm text-gray-600">Loading package...</p>
    </div>

    <div *ngIf="!loading && errorMessage" class="text-center py-8">
      <div class="text-red-500 mb-1">
        <svg class="w-3 h-3 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
      </div>
      <p class="text-sm text-red-600">{{ errorMessage }}</p>
    </div>

    <div *ngIf="!loading && !errorMessage && package" class="bg-white rounded-xl shadow-sm overflow-hidden border border-gray-100">
      <div class="grid grid-cols-1 lg:grid-cols-2 gap-6 p-6">
        <div>
          <div class="aspect-square rounded-lg overflow-hidden bg-gray-100 mb-4">
            <img [src]="package.thumbnail || package.images?.[0] || 'https://via.placeholder.com/300'"
              [alt]="package.title" class="w-full h-full object-cover" />
          </div>
          <div *ngIf="package.images && package.images.length > 1" class="grid grid-cols-4 gap-2">
            <div *ngFor="let image of package.images; let i = index" (click)="currentImage = image"
              [ngClass]="{ 'border-primary': currentImage === image, 'border-transparent hover:border-gray-300': currentImage !== image }"
              class="aspect-square rounded-lg overflow-hidden bg-gray-100 cursor-pointer border-2 transition-colors">
              <img [src]="image" [alt]="package.title + ' ' + (i + 1)" class="w-full h-full object-cover" />
            </div>
          </div>
        </div>

        <div>
          <h1 class="text-2xl font-bold text-gray-900 mb-2">{{ package.title }}</h1>
          <p class="text-sm text-gray-600 mb-4">{{ package.description }}</p>

          <div *ngIf="package.brand" class="flex justify-between mb-3">
            <span class="text-sm text-gray-600">Vendor:</span>
            <span class="text-sm font-medium text-gray-900">{{ package.brand }}</span>
          </div>

          <div *ngIf="package.category" class="flex justify-between mb-4">
            <span class="text-sm text-gray-600">Category:</span>
            <span class="text-sm font-medium text-gray-900">{{ package.category }}</span>
          </div>

          <div class="mb-4">
            <label class="block text-xs font-medium text-gray-700 mb-1 uppercase tracking-wider">Quantity</label>
            <input [(ngModel)]="quantity" name="quantity" type="number" min="1" [max]="package.stock || 1"
              class="input-field w-20" />
          </div>

          <div *ngIf="successMessage" class="mb-3 p-3 bg-green-50 border border-green-100 rounded-md">
            <p class="text-xs text-green-700 font-medium">{{ successMessage }}</p>
          </div>

          <div *ngIf="errorMessage" class="mb-3 p-3 bg-red-50 border border-red-100 rounded-md">
            <p class="text-xs text-red-600">{{ errorMessage }}</p>
          </div>

          <button (click)="placeOrder()" [disabled]="placing || quantity < 1"
            class="w-full bg-primary text-white py-2 rounded-md font-medium text-sm hover:bg-primary-dark transition-colors disabled:opacity-50 disabled:cursor-not-allowed">
            <span *ngIf="placing">Placing Order...</span>
            <span *ngIf="!placing">Place Order</span>
          </button>
        </div>
      </div>
    </div>
  </main>
</div>
